    38    ESTree::NodeList &body = prog->_body;
    39    if (body.size() != 1) {
    40      return false;
    41    }
    42    auto *exprStatement =
    43        llvh::dyn_cast<ESTree::ExpressionStatementNode>(&body.front());
    44    if (!exprStatement) {
    45      return false;
    46    }
    47    return llvh::isa<ESTree::FunctionExpressionNode>(
    48               exprStatement->_expression) ||
    49        llvh::isa<ESTree::ArrowFunctionExpressionNode>(
    50               exprStatement->_expression);
    51  }
